#!/usr/bin/env bash
# Question 1: Service ${Q1_APP} unreachable. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: http }
            periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
spec:
  selector: { app: ${Q1_APP} }
  ports: [{ port: 80, targetPort: http }]
---
apiVersion: v1
kind: Pod
metadata:
  name: ${Q1_CLIENT}
  namespace: ${Q1_NS}
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
EOF
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}-admin
  namespace: ${Q1_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: ${Q1_APP}-admin }
  template:
    metadata:
      labels: { app: ${Q1_APP}-admin, tier: admin }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q1_APP}-admin
  namespace: ${Q1_NS}
spec:
  selector: { app: ${Q1_APP}-admin }
  ports: [{ port: 8080, targetPort: http }]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: ${Q1_APP}-admin-ingress
  namespace: ${Q1_NS}
spec:
  podSelector:
    matchLabels: { app: ${Q1_APP}-admin }
  policyTypes: [Ingress]
  ingress:
    - from: [{ podSelector: { matchLabels: { role: ops } } }]
      ports: [{ protocol: TCP, port: 80 }]
EOF
kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"
if ! kubectl -n "${Q1_NS}" wait --for=condition=Ready "pod/${Q1_CLIENT}" --timeout=180s; then
  kubectl -n "${Q1_NS}" describe "pod/${Q1_CLIENT}" >&2 || true
  exit 1
fi

(
case "${Q1_FAULT}" in
  selector-mismatch)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" -p '{"spec":{"selector":{"app":"'"${Q1_APP}"'-v2"}}}'
    ;;
  target-port)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/ports/0/targetPort","value":8080}]'
    ;;
  selector-extra-label)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" -p '{"spec":{"selector":{"tier":"web"}}}'
    ;;
  service-port)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/ports/0/port","value":8080}]'
    ;;
  service-protocol)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/ports/0/protocol","value":"UDP"}]'
    ;;
  selector-cleared)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" --type=json -p '[{"op":"remove","path":"/spec/selector"}]'
    ;;
  target-port-typo)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/ports/0/targetPort","value":"htt"}]'
    ;;
  service-externalname)
    kubectl -n "${Q1_NS}" delete service "${Q1_APP}" --wait=true
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Service","metadata":{"name":"'"${Q1_APP}"'","namespace":"'"${Q1_NS}"'"},"spec":{"type":"ExternalName","externalName":"nowhere.invalid"}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  named-port)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/ports/0/name","value":"web"},{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/port","value":"web"}]'
    ;;
  not-ready)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/path","value":"/ready"}]'
    ;;
  readiness-https)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/scheme","value":"HTTPS"}]'
    ;;
  readiness-port-number)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/port","value":8080}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_3}" in
  network-policy)
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"networking.k8s.io/v1","kind":"NetworkPolicy","metadata":{"name":"'"${Q1_APP}"'-ingress"},"spec":{"podSelector":{"matchLabels":{"app":"'"${Q1_APP}"'"}},"policyTypes":["Ingress"],"ingress":[{"from":[{"podSelector":{"matchLabels":{"role":"monitoring"}}}]}]}}'
    ;;
  kube-proxy-down)
    kubectl -n kube-system patch daemonset kube-proxy -p '{"spec":{"template":{"spec":{"nodeSelector":{"kube-proxy":"disabled"}}}}}'
    kubectl -n kube-system wait --for=delete pod -l k8s-app=kube-proxy --timeout=180s >/dev/null 2>&1 || true
    ;;
  egress-network-policy)
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"networking.k8s.io/v1","kind":"NetworkPolicy","metadata":{"name":"deny-egress"},"spec":{"podSelector":{},"policyTypes":["Egress"]}}'
    ;;
  kube-proxy-config-mode)
    kubectl -n kube-system get configmap kube-proxy -o jsonpath='{.data.config\.conf}' > /tmp/cka-kube-proxy.conf
    cp -a /tmp/cka-kube-proxy.conf /tmp/cka-kube-proxy.conf.bak
    sed -i -E 's/^mode: .*/mode: not-a-mode/' /tmp/cka-kube-proxy.conf
    grep -qE '^mode: not-a-mode$' /tmp/cka-kube-proxy.conf || { echo "could not set kube-proxy mode" >&2; exit 1; }
    kubectl -n kube-system patch configmap kube-proxy --type merge -p "$(python3 -c 'import json,pathlib; print(json.dumps({"data":{"config.conf": pathlib.Path("/tmp/cka-kube-proxy.conf").read_text()}}))')"
    kubectl -n kube-system rollout restart daemonset/kube-proxy
    for _ in $(seq 1 60); do
      ready=$(kubectl -n kube-system get pods -l k8s-app=kube-proxy -o jsonpath='{range .items[*]}{.status.containerStatuses[0].ready}{"\n"}{end}' | grep -c true || true)
      [[ "$ready" == 0 ]] && break
      sleep 2
    done
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
kubectl -n "${Q1_NS}" scale "deployment/${Q1_APP}" --replicas=2
# The question only makes sense if the client really is cut off: give the Pods time to start,
# then require several failed requests in a row.
sleep 20
for _ in $(seq 1 5); do
  if kubectl -n "${Q1_NS}" exec "${Q1_CLIENT}" -- wget -qO- -T 3 "http://${Q1_APP}" 2>/dev/null | grep -q nginx; then
    echo "the client can still reach the service" >&2
    exit 1
  fi
  sleep 2
done
)
